                                ]
                            },
                            "minItems": 1,
                            "title": "Any",
                            "type": "array"
                        }
                    },
                    "required": [
                        "any"
                    ],
                    "title": "AnyGroup",
                    "type": "object"
                },
                "BetweenCondition": {
                    "additionalProperties": false,
                    "properties": {
                        "op": {
                            "const": "between",
